const crypto = require('crypto');
const item = $input.first().json;
const header = (item.headers && item.headers['stripe-signature']) || '';
const secret = process.env.STRIPE_WEBHOOK_SECRET || '';
let raw = '';
if ($input.first().binary && $input.first().binary.data) {
  raw = Buffer.from($input.first().binary.data.data, 'base64').toString('utf8');
}
if (!raw) raw = JSON.stringify(item.body || {});
const parts = {};
header.split(',').forEach(p => { const idx = p.indexOf('='); if (idx !== -1) parts[p.slice(0, idx)] = p.slice(idx + 1); });
const timestamp = parts.t || '';
const signature = parts.v1 || '';
const signedPayload = `${timestamp}.${raw}`;
const expected = crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');
let valid = false;
try {
  const a = Buffer.from(signature, 'hex');
  const b = Buffer.from(expected, 'hex');
  valid = a.length === b.length && a.length > 0 && crypto.timingSafeEqual(a, b);
} catch (e) { valid = false; }
if (valid) { const age = Math.abs(Date.now() / 1000 - parseInt(timestamp || '0', 10)); if (age > 300) valid = false; }
if (!valid) {
  try {
    await Postgres.main.query(`INSERT INTO workflows.workflow_errors (workflow_id, workflow_name, execution_id, error_type, message, node_id, node_type, severity, created_at) VALUES ('wf2-billing-lifecycle','WF-2: Billing & Customer Lifecycle',$1,'webhook.auth','Invalid Stripe signature','Verify Stripe Signature','webhook','high',CURRENT_TIMESTAMP)`, [$execution.id]);
  } catch (e) {}
  return [];
}
return [{ json: item }];

const body = $input.first().json.body;
const event = body.data?.object;
const eventType = body.type || '';
const validTypes = ['customer.subscription.created', 'customer.subscription.updated', 'customer.subscription.deleted', 'invoice.paid', 'invoice.payment_failed', 'checkout.session.completed'];
if (!validTypes.includes(eventType)) return [{ json: { skip: true } }];
return [{ json: { skip: false, eventType, event } }];

const { eventType, event } = $input.first().json;
const postgres = Postgres.main;
let action = 'unknown';
let metadata = { eventType };

switch (eventType) {
  case 'customer.subscription.created': {
    const r = await postgres.query(`INSERT INTO customers (stripe_customer_id, email, name, plan, status, created_at) VALUES ($1, $2, $3, $4, 'active', CURRENT_TIMESTAMP) ON CONFLICT (stripe_customer_id) DO UPDATE SET email=EXCLUDED.email, name=EXCLUDED.name, plan=EXCLUDED.plan, status='active', updated_at=CURRENT_TIMESTAMP RETURNING id, email`, [event.customer, event.metadata?.email||'', event.metadata?.name||'', event.metadata?.plan||'starter']);
    await postgres.query(`INSERT INTO mrr_events (customer_id, amount, event_type, created_at) VALUES ($1, $2, 'subscription.created', CURRENT_TIMESTAMP)`, [r.rows[0].id, (event.items?.data?.[0]?.price?.unit_amount||0)/100]);
    action = 'created'; metadata = { ...metadata, customerId: r.rows[0].id };
    break;
  }
  case 'customer.subscription.updated': {
    const amt = (event.items?.data?.[0]?.price?.unit_amount||0)/100;
    await postgres.query(`UPDATE customers SET plan=$1, updated_at=CURRENT_TIMESTAMP WHERE stripe_customer_id=$2`, [event.metadata?.plan||'starter', event.customer]);
    await postgres.query(`INSERT INTO mrr_events (customer_id, amount, event_type, created_at) VALUES ($1, $2, 'subscription.updated', CURRENT_TIMESTAMP)`, [event.customer, amt]);
    action = 'updated'; metadata = { ...metadata, amount: amt };
    break;
  }
  case 'customer.subscription.deleted': {
    await postgres.query(`UPDATE customers SET status='cancelled', updated_at=CURRENT_TIMESTAMP WHERE stripe_customer_id=$1`, [event.customer]);
    await postgres.query(`INSERT INTO mrr_events (customer_id, amount, event_type, created_at) VALUES ($1, $2, 'cancellation', CURRENT_TIMESTAMP)`, [event.customer, (event.items?.data?.[0]?.price?.unit_amount||0)/100]);
    action = 'deleted'; metadata = { ...metadata, customerId: event.customer };
    break;
  }
  case 'invoice.paid': { action = 'invoice_paid'; metadata = { ...metadata, amount: (event.amount_paid||0)/100 }; break; }
  case 'invoice.payment_failed': {
    const cr = await postgres.query(`SELECT id FROM customers WHERE stripe_customer_id=$1`, [event.customer]);
    await postgres.query(`INSERT INTO invoice_events (customer_id, stripe_customer_id, event_type, amount, status, created_at) VALUES ($1,$2,$3,$4,'failed',CURRENT_TIMESTAMP)`, [cr.rows[0]?.id||null, event.customer, 'invoice.payment_failed', (event.amount_due||0)/100]);
    action = 'payment_failed'; break;
  }
  case 'checkout.session.completed': { action = 'checkout_completed'; break; }
}

const totalR = await postgres.query(`SELECT COALESCE(SUM(amount),0) as total FROM mrr_events WHERE event_type!='cancellation' AND customer_id NOT IN (SELECT customer_id FROM mrr_events WHERE event_type='cancellation')`);
const totalMRR = parseFloat(totalR.rows[0].total || 0);

const msgs = {
  created: `✅ New subscription. MRR: $${totalMRR}`,
  updated: `🔄 Subscription updated. MRR: $${totalMRR}`,
  deleted: `❌ Subscription cancelled. MRR: $${totalMRR}`,
  payment_failed: `⚠️ Payment failed.`,
  invoice_paid: `💰 Invoice paid.`,
  checkout_completed: `🛒 Checkout completed.`,
  unknown: `ℹ️ Stripe event processed.`
};

return [{ json: { channel: '#billing-events', severity: action === 'payment_failed' ? 'high' : 'low', dedupeKey: `stripe_${action}_${event?.id || Date.now()}`, text: msgs[action] || msgs.unknown, metadata: { flow: 'stripe_event', action, totalMRR, ...metadata } } }];

const postgres = Postgres.main;
const yesterday = new Date(Date.now() - 86400000);
const mrr = await postgres.query(`SELECT COALESCE(SUM(amount),0) as total FROM mrr_events WHERE event_type!='cancellation' AND customer_id NOT IN (SELECT customer_id FROM mrr_events WHERE event_type='cancellation')`);
const newC = await postgres.query(`SELECT COUNT(*) as count FROM mrr_events WHERE event_type='subscription.created' AND created_at>=$1`, [yesterday.toISOString()]);
const churn = await postgres.query(`SELECT COUNT(*) as count, COALESCE(SUM(amount),0) as mrr FROM mrr_events WHERE event_type='cancellation' AND created_at>=$1`, [yesterday.toISOString()]);
const total = parseFloat(mrr.rows[0].total||0);
const churnMRR = parseFloat(churn.rows[0].mrr||0);
const churnRate = total > 0 ? ((churnMRR / total) * 100).toFixed(2) : 0;
return [{ json: { channel: '#metrics-daily', severity: 'low', dedupeKey: `mrr_${new Date().toISOString().split('T')[0]}`, text: `📊 *Daily MRR*
*Current:* $${total}
*New:* ${newC.rows[0].count}
*Churned:* ${churn.rows[0].count}
*Churn Rate:* ${churnRate}%`, metadata: { flow: 'daily_mrr', mrr: total, churnRate } } }];

const postgres = Postgres.main;
const thirtyAgo = new Date(Date.now() - 30*86400000);
const r = await postgres.query(`SELECT id, email, name FROM customers WHERE status='active' AND last_active_at<$1 AND reengagement_sent=false LIMIT 50`, [thirtyAgo.toISOString()]);
return r.rows.map(row => ({ json: { ...row, channel: '#customer-success', severity: 'low', dedupeKey: `reeng_${row.id}`, text: `🔄 *Re-engagement*
*Customer:* ${row.name} (${row.email})
*Action:* Send re-engagement campaign`, metadata: { flow: 'reengagement', email: row.email } } }));
